import openpyxl
from openpyxl.utils import get_column_letter, column_index_from_string
wb=openpyxl.load_workbook('/root/data/workbook.xlsx', data_only=False)
ws=wb['Data']
for r in range(15,23):
    vals=[]
    for c in range(1,13):
        v=ws.cell(row=r,column=c).value
        if v is not None:
            vals.append(f'{get_column_letter(c)}{r}={v!r}')
    if vals:
        print(' | '.join(vals))
    else:
        print(f'Row {r}: <all None in A-L>')

print('\nCheck year header candidates:')
for r in range(15,23):
    years=[ws[f'{col}{r}'].value for col in ['H','I','J','K','L']]
    if any(y is not None for y in years):
        print(r, years)
