import openpyxl
from openpyxl.utils import get_column_letter
wb=openpyxl.load_workbook('/root/data/workbook.xlsx', data_only=False)
ws=wb['Data']
print('Merged ranges count:', len(ws.merged_cells.ranges))
# show merged ranges around row 20-22
near=[]
for r in ws.merged_cells.ranges:
    if r.min_row<=22 and r.max_row>=18:
        near.append(str(r))
print('Merged ranges rows 18-22:', near)

# find cells containing 2019..2023
targets=set([2019,2020,2021,2022,2023,'2019','2020','2021','2022','2023'])
found=[]
for row in ws.iter_rows(min_row=1, max_row=100, min_col=1, max_col=30):
    for cell in row:
        if cell.value in targets:
            found.append((cell.coordinate, cell.value))
print('Year-like cells found:', found)

# find first 50 rows non-empty counts and max col
def row_summary(r):
    maxc=0
    non=0
    for c in range(1, ws.max_column+1):
        v=ws.cell(row=r,column=c).value
        if v is not None:
            non+=1
            maxc=max(maxc,c)
    return non,maxc
print('Data max_row', ws.max_row, 'max_col', ws.max_column)
for r in range(1,45):
    non,maxc=row_summary(r)
    if non:
        print(f'Row {r}: nonempty={non}, maxcol={get_column_letter(maxc)}')

# Show row 1-5 cells that have any value
for r in range(1,10):
    vals=[]
    for c in range(1,21):
        v=ws.cell(row=r,column=c).value
        if v is not None:
            vals.append(f'{get_column_letter(c)}{r}={v!r}')
    if vals:
        print(' | '.join(vals))
